fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Use zip to iterate over both vectors simultaneously
    // Map each pair to the comparison result
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x >= y)
        .collect()
}